SELECT COUNT(*) FROM POSTS p JOIN USERS u ON u.USER_ID = p.USER_ID JOIN CATEGORY c ON c.CATEGORY_ID = p.CATEGORY_ID LEFT JOIN TEAMS t ON t.TEAM_ID = p.TEAM_ID WHERE p.IS_BLIND = 'N' AND p.CATEGORY_ID IN
#{categoryId}
AND p.TEAM_ID IS NULL
AND p.TEAM_ID IS NOT NULL
AND p.TEAM_ID = #{teamId}
AND LOWER(p.TITLE) LIKE '%' || LOWER(#{keyword}) || '%' ESCAPE '!'
